UPDATE pre_order
pre_order_sn = #{preOrderSn}, user_id = #{userId}, train_id = #{trainId}, total_amount = #{totalAmount}, expire_time = #{expireTime}, status = #{status}, create_time = #{createTime},
where id = #{id}

UPDATE pre_order_details
temp_seat_no = CASE id
WHEN #{detail.id} THEN #{detail.tempSeatNo}
ELSE temp_seat_no END
WHERE id IN
#{detail.id}
